import json, pathlib, collections
root=pathlib.Path(__file__).parent
lessons=[('A',1,'Làm quen với trí tuệ nhân tạo','5–8'),('A',2,'Trí tuệ nhân tạo trong khoa học và đời sống','9–13'),('B',3,'Một số thiết bị mạng thông dụng','14–20'),('B',4,'Giao thức mạng','21–25'),('B',5,'Thực hành chia sẻ tài nguyên trên mạng','26–33'),('C',6,'Giao tiếp và ứng xử trong không gian mạng','34–38')]
L={n:dict(topic=t,id=n,title=name,pages=p) for t,n,name,p in lessons}
bank=[]
def add(n,level,section,q,opts,ex):
    i=len(bank); opts=opts.split('|'); answer=i%4; opts=opts[-answer:]+opts[:-answer] if answer else opts
    bank.append(dict(id=f'q{i+1}',type='mcq',topic=L[n]['topic'],lesson=n,level=level,section=section,question=q,options=opts,answer=answer,explanation=ex,review=f'Bài {n} – {section} (trang {L[n]["pages"]})'))
def rows(n,level,section,s):
    for line in s.strip().split('\n'):
        q,opts,ex=line.split(' :: ');add(n,level,section,q,opts,ex)
rows(1,'NB','1. Khái niệm về AI','''Phép thử Turing được đề xuất nhằm xem xét điều gì? :: Khả năng thể hiện hành vi thông minh.|Khả năng lưu trữ tệp có kích thước lớn.|Khả năng cung cấp điện cho các thiết bị.|Khả năng truyền tín hiệu trên cáp quang. :: Phép thử Turing mở đầu cách đánh giá khả năng máy tính thể hiện hành vi thông minh.
Hội thảo Dartmouth năm 1956 có ý nghĩa nào đối với AI? :: Đánh dấu sự ra đời của thuật ngữ AI.|Đánh dấu sự ra đời của mạng Internet.|Đánh dấu sự ra đời của thư điện tử.|Đánh dấu sự ra đời của cáp quang. :: Hội thảo Dartmouth là dấu mốc ra đời thuật ngữ AI.
Hệ thống gợi ý video dựa trên lịch sử xem thể hiện rõ khả năng nào? :: Học từ dữ liệu để điều chỉnh gợi ý.|Chép các tệp để tăng số bản lưu trữ.|Cấp năng lượng để duy trì màn hình.|Chuyển tín hiệu để nối các dây dẫn. :: Hệ thống học sở thích từ lịch sử xem để đề xuất video phù hợp.
Kĩ thuật nhận ra người đi bộ qua camera thể hiện khả năng nào? :: Cảm nhận và hiểu môi trường xung quanh.|Sao chép và lưu tệp vào ổ đĩa ngoài.|Kích hoạt và ngắt nguồn điện định kì.|Đóng gói và gửi tệp qua mạng nội bộ. :: Đó là khả năng nhận thức dựa trên cảm biến và dữ liệu đầu vào.
Trong phân loại AI, AI hẹp có đặc điểm nào? :: Được thiết kế cho một nhiệm vụ cụ thể.|Được thiết kế để làm mọi việc như người.|Được thiết kế để tự hiểu mọi lĩnh vực.|Được thiết kế để có đủ mọi tri thức. :: AI hẹp phục vụ nhiệm vụ cụ thể, không có năng lực tổng quát như con người.''')
rows(1,'NB','2. Một số ứng dụng của AI','''MYCIN là ví dụ điển hình của loại hệ thống nào? :: Hệ chuyên gia hỗ trợ chẩn đoán bệnh.|Hệ điều hành quản lí các tệp dữ liệu.|Hệ định tuyến kết nối các mạng cục bộ.|Hệ lưu trữ sao chép các tệp dự phòng. :: MYCIN là hệ chuyên gia y học dựa trên các luật suy diễn.
Nhận dạng chữ viết tay chuyển dữ liệu theo hướng nào? :: Từ ảnh chữ viết sang văn bản xử lí được.|Từ tệp văn bản sang nguồn điện ổn định.|Từ địa chỉ mạng sang tín hiệu âm thanh.|Từ bản ghi âm sang cổng kết nối vật lí. :: Nhận dạng chữ viết tay biến ảnh chữ thành dữ liệu văn bản có thể xử lí.
Trợ lí ảo thường tương tác với người dùng bằng cách nào? :: Hiểu yêu cầu bằng giọng nói tự nhiên.|Nhận lệnh từ dao động nguồn điện lưới.|Đọc yêu cầu từ màu sắc dây cáp mạng.|Nhận lệnh qua kích thước ổ đĩa cứng. :: Trợ lí ảo có thể hiểu giọng nói và hỗ trợ gọi điện, tìm kiếm, nhắc việc.
Ứng dụng nào gắn trực tiếp với khả năng hiểu ngôn ngữ? :: Dịch nội dung giữa các ngôn ngữ tự nhiên.|Sao lưu nội dung giữa các ổ đĩa lưu trữ.|Truyền tệp ảnh giữa các máy trong mạng.|Chia nguồn điện giữa các thiết bị ngoại vi. :: Dịch máy cần hiểu và xử lí ngôn ngữ tự nhiên.''')
rows(1,'TH','1. Khái niệm về AI','''Vì sao bộ hẹn giờ bật đèn theo lịch chưa đủ để gọi là AI? :: Nó chỉ lặp lại thao tác đã được ấn định.|Nó chỉ sử dụng nguồn điện đã ổn định.|Nó chỉ hoạt động trong phạm vi gia đình.|Nó chỉ được lắp đặt cùng một bóng đèn. :: Tự động hóa thao tác cố định không đồng nghĩa với có đặc trưng trí tuệ.
Hệ thống suy luận khác việc chỉ lưu dữ liệu ở điểm nào? :: Dùng logic và tri thức để rút ra kết luận.|Dùng dung lượng ổ đĩa để tăng số bản sao.|Dùng băng thông kết nối để tăng tốc tải.|Dùng nguồn điện dự phòng để tăng giờ chạy. :: Suy luận vận dụng logic và tri thức, không chỉ bảo quản dữ liệu.
Một ứng dụng kết hợp nhận thức và hiểu ngôn ngữ có thể làm gì? :: Nhận biển báo rồi mô tả bằng lời nói.|Lưu bản sao rồi tăng dung lượng ổ đĩa.|Bật nguồn máy rồi cấp điện cho màn hình.|Nối dây mạng rồi tăng số cổng bộ chia. :: Nhận biển báo cần nhận thức; mô tả bằng lời cần xử lí ngôn ngữ.''')
rows(1,'TH','2. Một số ứng dụng của AI','''MYCIN không dùng học máy nhưng vẫn được coi là AI vì sao? :: Nó dùng tri thức và luật để suy luận.|Nó có phần cứng với dung lượng rất lớn.|Nó được nối vào mạng với tốc độ rất cao.|Nó có nguồn điện với công suất rất lớn. :: AI không đồng nhất với học máy; hệ chuyên gia vẫn có khả năng suy luận.''')
rows(1,'VD','2. Một số ứng dụng của AI','''Thư viện cần nhập nội dung từ hàng nghìn phiếu viết tay. Nên chọn giải pháp nào? :: Dùng nhận dạng chữ để tạo văn bản số.|Dùng bộ định tuyến để tăng cổng mạng.|Dùng bộ hẹn giờ để bật đèn đúng lịch.|Dùng bộ chia điện để cấp nguồn liên tục. :: Nhận dạng chữ viết tay phù hợp chuyển phiếu giấy thành dữ liệu có thể xử lí.
Một lớp muốn trợ lí nghe câu hỏi tiếng Việt rồi tìm tài liệu. Năng lực cần ưu tiên là gì? :: Xử lí ngôn ngữ để hiểu yêu cầu nói.|Sao chép ổ đĩa để nhân bản mọi thư mục.|Nén tệp dữ liệu để giảm chỗ lưu trữ.|Chia nguồn điện để cấp cho mọi máy in. :: Trợ lí cần hiểu ngôn ngữ tự nhiên dưới dạng tiếng nói.''')
rows(2,'NB','1. AI và sự phát triển của một số lĩnh vực','''AI trong y tế có thể hỗ trợ trực tiếp công việc nào? :: Phát hiện dấu hiệu bất thường trên ảnh.|Nối các dây điện cấp nguồn cho máy in.|Định tuyến gói dữ liệu giữa các mạng.|Sao chép toàn bộ tệp vào ổ đĩa ngoài. :: AI cải thiện ảnh y tế, tìm cấu trúc bất thường và hỗ trợ chẩn đoán.
Ứng dụng AI nào gắn với lĩnh vực tài chính, ngân hàng? :: Phát hiện giao dịch có dấu hiệu gian lận.|Đọc biển báo trên đường xe đang di chuyển.|Theo dõi tưới tiêu trong một trang trại.|Nhận diện tổn thương trong ảnh chụp y tế. :: Ngân hàng dùng AI để phân tích, phát hiện và ngăn chặn gian lận.
Học tập cá nhân hóa nhờ AI chú trọng điều gì? :: Đề xuất nội dung theo tiến độ từng người.|Cấp một nội dung bất biến cho mọi người.|Thay mọi bài tập bằng chép lại tài liệu.|Loại mọi phản hồi về quá trình học tập. :: AI theo dõi tiến trình để gợi ý nội dung phù hợp từng cá nhân.
AI trong nông nghiệp có thể hỗ trợ việc nào? :: Dự đoán mùa vụ từ dữ liệu môi trường.|Gán địa chỉ IP cho các máy trong mạng.|Chuyển tín hiệu số sang tín hiệu tương tự.|Chia sẻ máy in giữa các máy trong lớp. :: AI phân tích thời tiết, đất đai, cây giống để tối ưu chăm sóc và thu hoạch.
AI tạo sinh tập trung vào khả năng nào? :: Tạo nội dung mới từ thuật toán và mô hình.|Chỉ sao chép nguyên trạng mọi tệp nguồn.|Chỉ lưu dữ liệu mới vào một ổ đĩa cứng.|Chỉ truyền tín hiệu qua một dây cáp mạng. :: AI tạo sinh có thể tạo hình ảnh, âm thanh và văn bản.''')
rows(2,'NB','2. AI và một vài cảnh báo','''Nguy cơ về việc làm khi AI tự động hóa nhiều công việc là gì? :: Một số lao động có thể bị mất việc.|Mọi nghề nghiệp đều lập tức biến mất.|Mọi người lao động đều tăng thu nhập.|Một số cáp mạng có thể bị mất điện. :: Tự động hóa có thể gây áp lực thất nghiệp; không đồng nghĩa mọi nghề biến mất.
Nguy cơ quyền riêng tư của AI liên quan trực tiếp đến điều gì? :: Thu thập và lạm dụng dữ liệu cá nhân.|Tăng chiều dài của các dây cáp quang.|Tăng số cổng của các bộ chuyển mạch.|Thay màu sắc của các thiết bị mạng. :: Nhiều ứng dụng thu thập dữ liệu cá nhân nên có nguy cơ lạm dụng.
Khả năng thiếu minh bạch của AI còn được diễn tả bằng hình ảnh nào? :: Hộp đen khó giải thích cách ra quyết định.|Bộ chia chỉ phát tín hiệu ra mọi cổng.|Ổ đĩa chỉ lưu dữ liệu đã được sao chép.|Bộ hẹn giờ chỉ bật đèn theo lịch cố định. :: Nhiều mô hình khó giải thích quá trình hình thành quyết định.
Theo sách, AI tổng quát đang ở trạng thái nào? :: Vẫn là mục tiêu nghiên cứu và phát triển.|Đã thay thế con người trong mọi lĩnh vực.|Chỉ là tên khác của bộ chia mạng cục bộ.|Đã có đủ mọi năng lực của mọi con người. :: AI tổng quát với khả năng áp dụng tri thức liên lĩnh vực vẫn đang được nghiên cứu.''')
rows(2,'TH','1. AI và sự phát triển của một số lĩnh vực','''Vì sao phản hồi tức thì có ích trong học tập cá nhân hóa? :: Giúp điều chỉnh nội dung theo lỗi đang gặp.|Giúp xóa bỏ nhu cầu tự luyện của học sinh.|Giúp mọi học sinh có cùng một kết quả thi.|Giúp thay thế toàn bộ hoạt động của giáo viên. :: Phản hồi kịp thời giúp nhận biết khó khăn và điều chỉnh quá trình học.
Xe tự lái cần phối hợp nhiều năng lực AI vì sao? :: Vừa nhận môi trường vừa quyết định xử lí.|Chỉ cần lưu dữ liệu rồi tắt mọi cảm biến.|Chỉ cần tăng tốc xe rồi bỏ qua biển báo.|Vừa cấp điện máy in vừa sao chép thư mục. :: Xe cần nhận thức môi trường và suy luận, ra quyết định.''')
rows(2,'TH','2. AI và một vài cảnh báo','''Vì sao cần con người giám sát AI trong quyết định y tế? :: Quyết định sai có thể gây hại cho người.|Mô hình AI chỉ hoạt động khi không có mạng.|Dữ liệu y tế luôn đúng trong mọi trường hợp.|Mô hình AI chỉ được dùng để sao lưu ổ đĩa. :: Sai sót hoặc tấn công dữ liệu, mô hình có thể dẫn đến chẩn đoán sai.
Vì sao câu trả lời trôi chảy của chatbot chưa đủ chứng minh AI tổng quát? :: Khả năng dùng ngôn ngữ không là mọi trí tuệ.|Khả năng dùng ngôn ngữ không cần đến dữ liệu.|Khả năng dùng ngôn ngữ chỉ là nối cáp mạng.|Khả năng dùng ngôn ngữ chỉ là cấp nguồn điện. :: Năng lực trong một số nhiệm vụ không đồng nghĩa năng lực tổng quát như con người.''')
rows(2,'VD','2. AI và một vài cảnh báo','''Nhóm học sinh định tải hồ sơ sức khỏe của cả lớp lên chatbot công khai. Nên làm gì trước? :: Dừng tải và xem xét bảo vệ dữ liệu riêng.|Tải ngay và công bố đường dẫn cho cả trường.|Đổi tên tệp rồi tải nguyên hồ sơ lên mạng.|Nén tệp nhỏ rồi gửi cho mọi tài khoản lạ. :: Hồ sơ sức khỏe là thông tin nhạy cảm; cần bảo vệ quyền riêng tư, không tùy tiện cung cấp.
AI gợi ý chẩn đoán trái với dấu hiệu bác sĩ quan sát. Hướng xử lí phù hợp là gì? :: Kiểm chứng dữ liệu và nhờ bác sĩ đánh giá.|Chấp nhận ngay vì máy luôn chính xác tuyệt đối.|Công bố hồ sơ để người lạ quyết định thay.|Xóa mọi dấu hiệu bệnh để khớp kết quả máy. :: AI hỗ trợ, không thay thế trách nhiệm đánh giá chuyên môn và giám sát an toàn.''')
rows(3,'NB','1. Thiết bị mạng thông dụng','''Khi nhận tín hiệu ở một cổng, hub xử lí theo cách nào? :: Phát tín hiệu đến tất cả cổng còn lại.|Chỉ chuyển tín hiệu đến đúng cổng nhận.|Chuyển tín hiệu số thành ảnh để lưu trữ.|Chỉ chuyển tín hiệu sang một mạng xa. :: Hub phát tín hiệu ra mọi cổng còn lại nên dễ gây xung đột.
Switch chuyển dữ liệu trong LAN dựa trên cách nào? :: Xác định cổng nối với thiết bị nhận.|Phát đồng thời ra mọi cổng còn lại.|Đổi nội dung thành một bản dịch mới.|Tăng công suất nguồn điện của máy. :: Switch xác định cổng của thiết bị nhận để thiết lập kênh truyền.
WAP có chức năng chính nào trong mạng cục bộ? :: Kết nối thiết bị đầu cuối bằng Wi-Fi.|Chuyển mọi tệp văn bản thành ảnh màu.|Cung cấp nguồn điện cho máy in mạng.|Chuyển mọi địa chỉ IP thành tên miền. :: WAP là điểm truy cập không dây để nối thiết bị qua Wi-Fi.
Thiết bị nào dẫn đường dữ liệu giữa các mạng? :: Router chọn đường đi cho gói dữ liệu.|Hub khuếch tán tín hiệu ra mọi cổng.|Máy in chuyển nội dung số lên tờ giấy.|Ổ cứng lưu bản sao của các tệp dữ liệu. :: Router chuyển tiếp và định tuyến dữ liệu giữa các LAN trên mạng rộng.
Modem có chức năng nào theo nội dung bài học? :: Chuyển tín hiệu số và tương tự qua lại.|Chọn nội dung học tập riêng cho mỗi người.|Đưa ra luật suy diễn để chẩn đoán bệnh.|Chỉ cấp quyền đọc cho thư mục chia sẻ. :: Modem chuyển đổi tín hiệu số và tương tự, không thay đổi dữ liệu mang theo.
Cổng thường dùng để cắm cáp UTP nối máy tính là gì? :: Cổng RJ45 dành cho dây cáp nối mạng.|Cổng HDMI dành cho dây cáp truyền hình.|Cổng âm thanh dành cho dây tai nghe.|Cổng nguồn điện dành cho dây cấp điện. :: Cáp UTP bốn đôi dây xoắn dùng giắc RJ45.
Trên router, cổng LAN chủ yếu nối đến đâu? :: Các thiết bị nằm trong mạng cục bộ.|Các điểm cấp nguồn điện trong phòng.|Các đường truyền hình tới màn chiếu.|Các cảm biến nhiệt độ trong ổ cứng. :: Cổng LAN kết nối trực tiếp với LAN; cổng WAN kết nối phía mạng ngoài.
Wi-Fi dùng môi trường truyền tín hiệu nào? :: Sóng vô tuyến điện để truyền dữ liệu.|Luồng nước chảy để truyền dữ liệu.|Dòng khí nén mạnh để truyền dữ liệu.|Nguồn điện một chiều để truyền dữ liệu. :: Wi-Fi là bộ tiêu chuẩn truyền dữ liệu bằng sóng vô tuyến.
Modem GSM có thể kết nối Internet qua thành phần nào? :: Thẻ SIM của hệ thống thông tin di động.|Giắc HDMI của hệ thống trình chiếu ảnh.|Đĩa DVD của hệ thống lưu trữ ngoại tuyến.|Cáp nguồn của hệ thống cung cấp điện lưới. :: Modem GSM 3G/4G/5G có khe SIM để truy cập Internet qua mạng di động.''')
rows(3,'TH','1. Thiết bị mạng thông dụng','''Vì sao LAN nhiều máy thường ưu tiên switch thay cho hub? :: Hạn chế xung đột nhờ chuyển đúng cổng.|Tăng xung đột nhờ phát tín hiệu mọi cổng.|Tạo bản dịch nhờ xử lí mọi tệp văn bản.|Cấp nguồn điện nhờ kết nối mọi máy in. :: Switch không phát tràn mọi cổng như hub nên hoạt động hiệu quả hơn.
Vì sao chỉ cắm dây mạng có thể chưa truy cập được Internet? :: Còn cần thiết lập địa chỉ và kết nối logic.|Còn cần tăng độ sáng của màn hình máy tính.|Còn cần thay màu vỏ của mọi thiết bị mạng.|Còn cần đổi tên mọi tệp trong ổ đĩa cứng. :: Kết nối vật lí chưa đủ; còn cấu hình địa chỉ và khai báo kết nối.
Router Wi-Fi khác WAP đơn thuần ở điểm chính nào? :: Kết hợp định tuyến và truy cập không dây.|Chỉ làm công việc hiển thị các trang web.|Chỉ làm công việc lưu trữ các tệp văn bản.|Kết hợp in tài liệu và nhận dạng chữ viết. :: Router Wi-Fi tích hợp chức năng router và bộ thu phát Wi-Fi.
Vì sao modem không thay thế hoàn toàn chức năng router? :: Đổi tín hiệu khác với chọn đường dữ liệu.|Đổi tín hiệu luôn xóa hết nội dung dữ liệu.|Đổi tín hiệu chỉ làm tăng độ sáng màn hình.|Đổi tín hiệu chỉ làm giảm số lượng máy in. :: Modem chuyển dạng tín hiệu, còn router dẫn đường dữ liệu.''')
rows(3,'VD','2. Thực hành kết nối máy tính với thiết bị mạng','''Phòng học có 30 máy bàn cần trao đổi dữ liệu có dây, giảm xung đột. Nên dùng gì? :: Dùng switch đủ cổng để nối các máy.|Dùng hub đủ cổng để phát ra mọi nhánh.|Dùng máy in màu để nối các máy bàn.|Dùng bộ chia điện để nối các dây mạng. :: Switch phù hợp LAN có nhiều máy, hạn chế xung đột so với hub.
Máy tính bàn chưa có Wi-Fi cần vào mạng không dây của lớp. Cần bổ sung gì? :: Bộ mạch hoặc bộ điều hợp hỗ trợ Wi-Fi.|Bộ chuyển đổi hình ảnh hỗ trợ màn chiếu.|Bộ hộp mực in hỗ trợ in trang hai mặt.|Bộ nguồn dự phòng hỗ trợ cấp điện máy. :: Máy bàn cần có bộ phận hỗ trợ Wi-Fi rồi mới kết nối WAP.''')
rows(4,'NB','1. Giao thức mạng','''Giao thức mạng là tập hợp các quy định về điều gì? :: Cách giao tiếp để truyền dữ liệu qua mạng.|Cách mua sắm để thay bàn ghế phòng máy.|Cách cấp điện để bật màn hình trong lớp.|Cách trang trí để đổi màu vỏ máy tính. :: Giao thức quy định cách thức giao tiếp giữa các đối tượng truyền nhận dữ liệu.
Trong ví dụ thư điện tử, SMTP phục vụ công việc nào? :: Gửi thư điện tử theo các quy định chung.|Nhận thư điện tử về bằng cách đọc hộp thư.|Đổi tên miền chữ thành địa chỉ của máy.|Chọn đường truyền giữa các mạng cục bộ. :: SMTP là giao thức liên quan đến gửi thư; POP3 hoặc IMAP liên quan nhận thư.
Địa chỉ MAC trong bài học có độ dài bao nhiêu? :: Gồm 6 byte gắn với phần cứng thiết bị.|Gồm 4 byte gắn với phần cứng thiết bị.|Gồm 2 byte gắn với phần cứng thiết bị.|Gồm 8 byte gắn với phần cứng thiết bị. :: Sách mô tả MAC là địa chỉ 6 byte gắn với phần cứng.
Mã kiểm tra trong khung truyền dữ liệu giúp việc gì? :: Phát hiện dữ liệu bị lỗi trong khi truyền.|Nén toàn bộ dữ liệu thành một tệp nhỏ hơn.|Dịch toàn bộ nội dung sang tiếng nước ngoài.|Cấp lại nguồn điện cho thiết bị đang nhận. :: Máy nhận dùng mã kiểm tra để phát hiện lỗi và yêu cầu gửi lại khi cần.''')
rows(4,'NB','2. Giao thức TCP/IP','''IPv4 được mô tả trong bài học có độ dài bao nhiêu? :: Gồm 4 byte, tương ứng với 32 bit.|Gồm 6 byte, tương ứng với 48 bit.|Gồm 8 byte, tương ứng với 64 bit.|Gồm 2 byte, tương ứng với 16 bit. :: Địa chỉ IPv4 có 4 byte, thường viết bốn số thập phân phân tách bằng dấu chấm.
Chức năng chính của giao thức IP là gì? :: Quy định địa chỉ và định tuyến dữ liệu.|Quy định phông chữ và màu sắc văn bản.|Quy định khổ giấy và thứ tự trang in.|Quy định dung lượng và tên tệp lưu trữ. :: IP lập địa chỉ và định tuyến để dẫn dữ liệu từ LAN gửi đến LAN nhận.
TCP dùng thông tin nào để chuyển gói đến đúng ứng dụng? :: Số hiệu cổng được cấp cho ứng dụng.|Màu nền cửa sổ hiển thị ứng dụng.|Kích thước biểu tượng của ứng dụng.|Vị trí phím tắt khởi chạy ứng dụng. :: Cổng ứng dụng giúp TCP phân phối dữ liệu đến đúng ứng dụng.
DNS cho phép người dùng sử dụng điều gì thuận tiện hơn? :: Dùng tên bằng chữ thay địa chỉ IP.|Dùng mã nguồn điện thay địa chỉ IP.|Dùng kích thước tệp thay địa chỉ IP.|Dùng màu dây cáp thay địa chỉ IP. :: DNS cho phép dùng tên miền dễ nhớ thay cho địa chỉ IP.
Đánh số thứ tự các gói dữ liệu thuộc vai trò nào của TCP? :: Lắp lại dữ liệu đúng thứ tự ở nơi nhận.|Tăng độ sáng màn hình tại máy đang nhận.|Đổi tên thư mục chia sẻ trên máy nhận.|Tăng công suất nguồn điện tại máy nhận. :: Các gói có thể đến khác thứ tự nên TCP đánh số để lắp lại.''')
rows(4,'TH','2. Giao thức TCP/IP','''Các gói cùng một tệp đến sai thứ tự. Vì sao TCP vẫn khôi phục được tệp? :: Các gói có số thứ tự để lắp ghép lại.|Các gói có màu vỏ để phân biệt đường đi.|Các gói có thời hạn để tự xóa khỏi máy.|Các gói có mật khẩu để tăng tốc ổ đĩa. :: Số thứ tự hỗ trợ sắp xếp, lắp lại dữ liệu theo đúng trình tự.
Vì sao chỉ IP chưa đủ để phục vụ nhiều ứng dụng cùng lúc? :: IP đưa đến máy, TCP đưa đúng ứng dụng.|IP chỉ đổi màu, TCP chỉ đổi tên thư mục.|IP chỉ lưu ảnh, TCP chỉ in ra tài liệu.|IP đưa đến giấy, TCP đưa sang màn hình. :: IP xác định máy/mạng đích; cổng TCP phân biệt các ứng dụng trên máy.
Router không có mục khớp địa chỉ đích trong bảng định tuyến tĩnh thì sao? :: Chuyển gói dữ liệu theo cổng mặc định.|Chuyển gói dữ liệu thành một tệp ảnh.|Gửi mọi mật khẩu tới người đang nhận.|Gửi gói dữ liệu vào bộ nguồn dự phòng. :: Sách mô tả cổng mặc định dùng khi địa chỉ đích không có trong bảng.
Vì sao gói đi qua nhiều router vẫn đến được LAN đích? :: Mỗi router chọn chặng đi dựa vào địa chỉ.|Mỗi router chỉ nhân bản dữ liệu thành ảnh.|Mỗi router xóa địa chỉ trước khi chuyển gói.|Mỗi router tự thay nội dung bằng bản dịch. :: Router liên tiếp hướng dẫn dữ liệu dựa trên địa chỉ và bảng định tuyến.''')
rows(4,'VD','2. Giao thức TCP/IP','''Cho bảng định tuyến: 172.18.*.* qua cổng 2; mặc định qua cổng 1. Gói tới 172.18.5.9 đi đâu? :: Chuyển tiếp gói dữ liệu qua cổng số 2.|Chuyển tiếp gói dữ liệu qua cổng số 1.|Chuyển tiếp gói dữ liệu qua cổng số 3.|Chuyển tiếp gói dữ liệu qua cổng số 4. :: Địa chỉ đích khớp nhóm 172.18.*.* nên dùng cổng 2.
Byte đầu địa chỉ IPv4 là 11000000. Giá trị thập phân tương ứng là bao nhiêu? :: Giá trị của byte đầu tiên là 192.|Giá trị của byte đầu tiên là 128.|Giá trị của byte đầu tiên là 168.|Giá trị của byte đầu tiên là 224. :: 11000000 = 128 + 64 = 192.''')
rows(5,'NB','1. Chia sẻ tệp và thư mục trên mạng cục bộ','''Điều kiện cơ bản để hai máy chia sẻ tài nguyên qua LAN là gì? :: Có kết nối mạng và có quyền truy cập.|Có kết bạn mạng xã hội và có ảnh chung.|Có cùng màu màn hình và cùng tên tệp.|Có trả phí truy cập và có cùng bàn phím. :: Cần nối mạng và được chủ tài nguyên cấp quyền; không cần kết bạn hay trả phí.
Quyền Read với thư mục chia sẻ cho phép điều gì? :: Xem dữ liệu nhưng không được sửa dữ liệu.|Sửa dữ liệu nhưng không được xem dữ liệu.|Xóa dữ liệu nhưng không được đọc dữ liệu.|Đổi mọi quyền nhưng không được mở dữ liệu. :: Read chỉ cho đọc, không cho ghi sửa.
Quyền Read/Write với thư mục chia sẻ cho phép điều gì? :: Đọc và sửa nội dung trong phạm vi quyền.|Đọc và thay mọi mật khẩu của cả hệ thống.|Đọc và mở mọi tài khoản ngoài phạm vi mạng.|Đọc và tắt mọi biện pháp bảo mật của mạng. :: Read/Write cho đọc và ghi sửa tài nguyên được chia sẻ.
Tùy chọn Network discovery chủ yếu phục vụ điều gì? :: Cho các máy trong mạng tìm thấy máy này.|Cho các máy trong mạng đổi hết mật khẩu.|Cho các máy trong mạng xóa mọi phần mềm.|Cho các máy trong mạng tăng điện áp nguồn. :: Network discovery giúp máy được nhìn thấy trong mạng.
Để chọn người nhận quyền chia sẻ thư mục, dùng thao tác nào? :: Chọn người dùng rồi nhấn nút Add.|Chọn độ sáng rồi nhấn nút Apply.|Chọn khổ giấy rồi nhấn nút Print.|Chọn phông chữ rồi nhấn nút Save. :: Trong hộp chia sẻ, chọn người dùng rồi Add vào danh sách.
Để hủy chia sẻ một thư mục trong Advanced Sharing, làm gì? :: Bỏ dấu chọn ở mục Share this folder.|Đổi tên tệp trong mục Public Pictures.|Đổi hình nền ở mục Personalization.|Bật chế độ in trong mục Printer queue. :: Bỏ chọn Share this folder rồi OK/Apply để hủy chia sẻ.
Mạng Private trong bài được dùng chủ yếu cho đối tượng nào? :: Nhóm người dùng có độ tin cậy cao.|Nhóm khách lạ tại sân bay công cộng.|Nhóm quảng cáo từ tài khoản vô danh.|Nhóm thư rác từ địa chỉ chưa xác minh. :: Mạng riêng dành cho nhóm tin cậy, thuận lợi chia sẻ nội bộ.''')
rows(5,'NB','2. Chia sẻ máy in','''Máy tính cung cấp dịch vụ in trên mạng có vai trò gì? :: Nhận yêu cầu và xếp vào hàng đợi để in.|Nhận yêu cầu và dịch mọi tệp sang tiếng Anh.|Nhận yêu cầu và cấp địa chỉ cho Internet.|Nhận yêu cầu và xóa hết tài liệu trong mạng. :: Máy cung cấp dịch vụ in nhận yêu cầu, xếp hàng và điều khiển máy in.
Trong Printer properties, thẻ nào dùng thiết lập chia sẻ máy in? :: Thẻ Sharing dùng để chia sẻ máy in.|Thẻ Security dùng để đổi khổ giấy.|Thẻ General dùng để tạo tên miền.|Thẻ Ports dùng để đổi màu màn hình. :: Thẻ Sharing trong thuộc tính máy in phục vụ chia sẻ.''')
rows(5,'TH','1. Chia sẻ tệp và thư mục trên mạng cục bộ','''Máy B mở được tệp chia sẻ nhưng không lưu thay đổi. Nguyên nhân phù hợp nhất là gì? :: Máy B chỉ được cấp quyền đọc dữ liệu.|Máy B đã được cấp đầy đủ quyền ghi sửa.|Máy B chưa được nối vào bất kì mạng nào.|Máy B đang được cấp quyền quản trị mạng. :: Có thể mở nhưng không sửa phù hợp với quyền Read.
Vì sao không nên chia sẻ cả ổ đĩa cho mọi người theo mặc định? :: Có thể lộ hoặc bị sửa những dữ liệu riêng.|Có thể tăng độ sáng của tất cả màn hình.|Có thể tự tạo thêm cổng mạng cho router.|Có thể tự nâng tốc độ của mọi máy in. :: Chia sẻ quá rộng làm tăng rủi ro truy cập, sửa hoặc hỏng dữ liệu.
Hai máy đã nối cáp nhưng không truy cập được thư mục. Nên kiểm tra gì? :: Khám phá mạng, chế độ chia sẻ và quyền.|Độ sáng màn hình, hình nền và phông chữ.|Khổ giấy mặc định, màu mực và số bản in.|Tốc độ quạt tản nhiệt, màu vỏ và chân đế. :: Kết nối vật lí cần đi kèm cấu hình chia sẻ và quyền hợp lệ.''')
rows(5,'TH','2. Chia sẻ máy in','''Vì sao chia sẻ máy in giúp tiết kiệm tài nguyên trong văn phòng? :: Nhiều máy cùng sử dụng một thiết bị in.|Mỗi máy bắt buộc có riêng một thiết bị in.|Mọi tài liệu được tự động xóa ngay khi in.|Mọi máy tự tăng gấp đôi dung lượng ổ cứng. :: Dùng chung máy in giảm số thiết bị cần mua và tránh phải chép tệp thủ công.''')
rows(5,'VD','1. Chia sẻ tệp và thư mục trên mạng cục bộ','''Giáo viên muốn lớp xem tài liệu gốc nhưng không sửa. Nên cấp quyền nào? :: Cấp Read cho nhóm học sinh cần xem.|Cấp Read/Write cho mọi tài khoản lạ.|Cấp toàn quyền cho người dùng bất kì.|Cấp quyền sửa và xóa cho cả mạng ngoài. :: Read đáp ứng đọc tài liệu và hạn chế thay đổi bản gốc.
Kết thúc dự án, thư mục không cần chia sẻ nữa. Cách xử lí phù hợp là gì? :: Hủy chia sẻ và kiểm tra lại từ máy khác.|Đổi hình nền và giữ toàn quyền cho cả lớp.|Chép mật khẩu vào thư mục công cộng chung.|Chỉ đổi tên tệp mà vẫn giữ mọi quyền ghi. :: Hủy chia sẻ, kiểm tra lại khả năng truy cập giúp xác nhận quyền đã thu hồi.''')
rows(6,'NB','1. Giao tiếp trong không gian mạng','''Không gian mạng được tạo ra nhờ sử dụng yếu tố nào? :: Mạng máy tính và các dịch vụ liên quan.|Bàn ghế phòng học và các đồ vật trang trí.|Giấy viết truyền thống và các phong bì thư.|Thiết bị cấp điện và các công tắc cơ học. :: Không gian mạng là môi trường được tạo ra nhờ các mạng máy tính.
Tình huống nào là giao tiếp trong không gian mạng? :: Tham dự lớp học qua hội nghị trực tuyến.|Gặp bạn tại bàn ăn và trò chuyện trực tiếp.|Viết lời nhắn trên giấy rồi đặt lên bàn.|Đọc báo giấy tại phòng khách cùng gia đình. :: Lớp trực tuyến dùng dịch vụ giao tiếp qua mạng.
Ưu điểm thuận tiện của giao tiếp trực tuyến là gì? :: Có thể trao đổi từ xa khi có kết nối mạng.|Có thể trao đổi mà không cần thiết bị nào.|Có thể hiểu mọi cử chỉ dù chỉ gửi chữ viết.|Có thể bảo đảm mọi tài khoản đều chân thật. :: Giao tiếp trực tuyến thuận tiện khi có kết nối mạng.
Họp qua mạng thay cho đi xa giúp tiết kiệm chủ yếu điều gì? :: Thời gian và chi phí di chuyển của người.|Dung lượng và kích thước của ổ đĩa cứng.|Số cổng và chiều dài của bộ chuyển mạch.|Khổ giấy và lượng mực của máy in màu. :: Giao tiếp trực tuyến giảm nhu cầu đi lại và chi phí.
Một hạn chế của tin nhắn văn bản so với gặp trực tiếp là gì? :: Thiếu tín hiệu về nét mặt và giọng nói.|Thiếu khả năng lưu lại nội dung đã viết.|Thiếu khả năng truyền đi các kí tự chữ.|Thiếu khả năng liên hệ người ở xa hơn. :: Văn bản thiếu nhiều tín hiệu phi ngôn ngữ nên dễ gây hiểu nhầm.
Nguy cơ riêng tư trong giao tiếp trực tuyến thể hiện thế nào? :: Thông tin cá nhân có thể bị lộ hoặc lạm dụng.|Thời gian di chuyển có thể được giảm đáng kể.|Mạng quan hệ xã hội có thể được mở rộng hơn.|Công cụ liên lạc có thể được chọn đa dạng hơn. :: Rò rỉ thông tin và tấn công bảo mật đe dọa quyền riêng tư.
Điều gì có thể làm cuộc họp trực tuyến bị gián đoạn? :: Mất kết nối mạng hoặc lỗi phần mềm họp.|Đọc kĩ bài viết hoặc dùng lời nói lịch sự.|Tôn trọng người khác hoặc nghe ý kiến đủ.|Dùng lời động viên hoặc hỗ trợ bạn bè. :: Sự cố kĩ thuật là một nhược điểm của giao tiếp trực tuyến.
Khả năng mở rộng kết nối xã hội nhờ mạng thể hiện ở đâu? :: Kết nối nhiều người chung sở thích từ xa.|Giới hạn liên lạc trong cùng một bàn học.|Bắt buộc mọi người phải có mặt cùng phòng.|Loại bỏ mọi công cụ trò chuyện bằng chữ. :: Mạng giúp mở rộng quan hệ theo sở thích, quan điểm hoặc nhu cầu.
Công cụ nào thuộc nhóm giao tiếp trực tuyến? :: Thư điện tử và hội nghị truyền hình.|Thư giấy tay và phong bì chuyển phát.|Bảng phấn đen và tờ giấy thông báo.|Sổ ghi chép và hộp bút đặt trên bàn. :: Thư điện tử, nhắn tin, mạng xã hội, hội nghị truyền hình là các công cụ trực tuyến.''')
rows(6,'NB','2. Thể hiện tính nhân văn trong không gian mạng','''Yếu tố nào thuộc ứng xử nhân văn trên mạng? :: Tôn trọng, lịch sự, thấu hiểu và hỗ trợ.|Giễu cợt, công kích, thách thức và bêu xấu.|Phán xét, kích động, đe dọa và chụp mũ.|Gây hấn, áp đặt, xúc phạm và phát tán tin. :: Sách nêu bốn yếu tố tôn trọng, lịch sự, thấu hiểu và hỗ trợ.
Tôn trọng quyền riêng tư của bạn có nghĩa là gì? :: Không phát tán tin riêng khi chưa được phép.|Không đọc kĩ bài viết trước khi trao đổi.|Không bình tĩnh lắng nghe quan điểm khác.|Không hỗ trợ bạn bè khi đang cần giúp đỡ. :: Tin riêng chỉ được chia sẻ khi có sự cho phép.
Lịch sự khi phản biện trên mạng là cách nào? :: Dùng từ đúng mực và trao đổi có căn cứ.|Dùng từ thô tục và công kích người viết.|Dùng lời mỉa mai và quy chụp đối tượng.|Dùng lời đe dọa và kích động đám đông. :: Lịch sự đòi hỏi dùng ngôn từ đúng mực, tránh lăng mạ.
Thấu hiểu người khác trên mạng là gì? :: Đặt mình vào hoàn cảnh để hiểu khó khăn.|Đặt lời buộc tội để bác bỏ mọi ý kiến.|Đặt điều không có để làm người khác sợ.|Đặt ảnh riêng tư để gây sức ép đám đông. :: Thấu hiểu là cảm thông và hiểu khó khăn, suy nghĩ của người khác.
Hỗ trợ người khác trên mạng có thể thể hiện bằng gì? :: Gửi lời động viên và chia sẻ cách giúp đỡ.|Gửi lời chê bai và lặp lại lỗi của họ.|Gửi ảnh riêng tư và kêu gọi người xem.|Gửi lời kích động và thúc đẩy tranh cãi. :: Động viên, an ủi và giúp đỡ là các biểu hiện hỗ trợ.
Trước khi chia sẻ một bài viết, cần ưu tiên điều gì? :: Kiểm tra tính đúng và quyền riêng tư.|Kiểm tra lượt thích và bỏ qua nguồn tin.|Kiểm tra độ sốc và bỏ qua người bị nêu.|Kiểm tra tiêu đề và bỏ qua nội dung gốc. :: Cần đọc, kiểm chứng và tránh xâm phạm danh tiếng, quyền riêng tư.
Khi không đồng ý một bài viết, hành vi phù hợp là gì? :: Đọc kĩ nội dung rồi phản hồi lịch sự.|Đọc qua tiêu đề rồi xúc phạm tác giả.|Chụp ảnh riêng tư rồi kêu gọi tẩy chay.|Chuyển sang đe dọa rồi phát tán tin đồn. :: Đọc kĩ và trao đổi tôn trọng là ứng xử nhân văn.
Thói quen nào giúp cải thiện hành vi trực tuyến? :: Tự xem xét và điều chỉnh cách ứng xử.|Tự xóa mọi nguồn tin khác với ý mình.|Tự công bố mọi tin riêng của người khác.|Tự bỏ qua mọi ý kiến góp ý có căn cứ. :: Sách khuyến khích tự kiểm tra và cải thiện hành vi.
Trong cuộc gọi video, nên chú ý điều gì? :: Trang phục lịch sự và hậu cảnh phù hợp.|Trang phục gây sốc và hậu cảnh xúc phạm.|Trang phục bất kì và thái độ công kích.|Trang phục lố lăng và lời nói khiêu khích. :: Cần mặc lịch sự, tránh hậu cảnh phản cảm và giữ thái độ đúng đắn.''')
rows(6,'TH','1. Giao tiếp trong không gian mạng','''Vì sao nhắn tin ngắn có thể gây hiểu nhầm ý đùa? :: Thiếu giọng điệu và cử chỉ hỗ trợ diễn đạt.|Thiếu dây cáp riêng để cấp nguồn máy tính.|Thiếu máy in chung để sao chép nội dung.|Thiếu ổ đĩa lớn để lưu thêm các thư mục. :: Văn bản thiếu tín hiệu phi ngôn ngữ nên cảm xúc có thể bị hiểu sai.
Vì sao khó đánh giá sự chân thật của tài khoản lạ? :: Người dùng có thể ẩn danh hoặc giả mạo tên.|Người dùng luôn công khai đủ mọi giấy tờ.|Người dùng chỉ liên lạc khi ở cùng một phòng.|Người dùng luôn được người quen xác nhận. :: Mạng cho phép giấu mặt, tạo bản sao không đầy đủ hoặc giả thông tin.
Nhiều công cụ trực tuyến khác nhau mang lại lợi ích gì? :: Chọn hình thức phù hợp nhu cầu liên lạc.|Chọn bỏ toàn bộ biện pháp bảo vệ riêng tư.|Chọn thay mọi quan hệ cá nhân bằng máy.|Chọn bảo đảm không còn sự cố đường truyền. :: Sự đa dạng giúp chọn công cụ phù hợp; không xóa bỏ rủi ro.
Học sinh học online ở xa vẫn tham gia được vì sao? :: Giao tiếp qua mạng giảm giới hạn địa lí.|Giao tiếp qua mạng không cần kết nối nào.|Giao tiếp qua mạng không cần thiết bị nào.|Giao tiếp qua mạng loại bỏ mọi lỗi kĩ thuật. :: Khi có thiết bị và kết nối, người học có thể tham gia từ xa.''')
rows(6,'TH','2. Thể hiện tính nhân văn trong không gian mạng','''Vì sao gửi ảnh nhật kí riêng của bạn cho nhóm là không phù hợp? :: Xâm phạm riêng tư dù chưa đăng công khai.|Tăng độ chính xác của mọi thông tin trao đổi.|Tăng khả năng bảo mật của tài khoản cá nhân.|Tiết kiệm thời gian và chi phí di chuyển. :: Chia sẻ cho bên thứ ba khi chưa được phép vẫn xâm phạm riêng tư.
Vì sao lời góp ý nên tập trung vào lập luận thay vì con người? :: Tránh tổn thương và giữ đối thoại tôn trọng.|Tránh kiểm chứng và giữ mọi thông tin sai.|Tránh lắng nghe và giữ thái độ khiêu khích.|Tránh hỗ trợ và giữ mọi lời lăng mạ nhau. :: Phản biện lịch sự, không tấn công cá nhân giúp trao đổi lành mạnh.
Vì sao cần cẩn trọng với ngôn từ và cách viết trên mạng? :: Tránh hiểu lầm và gây kích thích đối phương.|Tránh sử dụng bất kì công cụ trực tuyến nào.|Tránh trao đổi mọi quan điểm khác biệt nhau.|Tránh lưu trữ bất kì nội dung học tập nào. :: Từ ngữ thiếu phù hợp có thể gây hiểu nhầm và kích động tranh cãi.
Một lời an ủi chân thành có giá trị hỗ trợ như thế nào? :: Giúp người gặp khó khăn cảm thấy được sẻ chia.|Giúp người gặp khó khăn bị lộ hết đời tư.|Giúp người gặp khó khăn bị chỉ trích nhiều hơn.|Giúp người gặp khó khăn bị cô lập trong nhóm. :: Hỗ trợ không chỉ vật chất mà còn là động viên, an ủi kịp thời.''')
rows(6,'VD','2. Thể hiện tính nhân văn trong không gian mạng','''Bạn nhận video hai học sinh đánh nhau kèm lời mời chia sẻ. Nên làm gì? :: Không phát tán, báo người có trách nhiệm.|Phát tán ngay, kèm lời chê bai hai học sinh.|Đăng ảnh mặt, kèm thông tin riêng hai bạn.|Đổi tiêu đề, kèm lời kêu gọi đám đông xem. :: Không lan truyền nội dung gây tổn thương; tìm hỗ trợ có trách nhiệm.
Bạn thấy thông tin chưa rõ nguồn nói xấu một bạn cùng lớp. Nên xử lí thế nào? :: Kiểm chứng, không tiếp tay lan truyền tin.|Chia sẻ, thêm nhận xét để tăng lượt xem.|Chụp ảnh, gửi cho nhiều nhóm chưa quen.|Đăng lại, gắn tên để tạo sức ép cho bạn. :: Cần kiểm chứng và bảo vệ danh tiếng, riêng tư của người khác.
Trong nhóm học tập, bạn mới hiểu sai một thuật ngữ rồi hỏi lại. Nên phản hồi ra sao? :: Giải thích rõ và động viên bạn tiếp tục hỏi.|Chế giễu ngay và yêu cầu bạn rời khỏi nhóm.|Chụp câu hỏi và đăng kèm lời mỉa mai bạn.|Gạt ý kiến và từ chối mọi hỗ trợ cho bạn. :: Thấu hiểu, lịch sự và hỗ trợ giúp xây dựng môi trường học tập tích cực.
Bạn tức giận vì bị phản bác trên diễn đàn. Cách xử lí phù hợp nhất là gì? :: Bình tĩnh, đọc kĩ và trao đổi có lập luận.|Nóng giận, lăng mạ và công bố tin riêng.|Kích động, quy chụp và gọi đám đông vào.|Đe dọa, chụp mũ và bỏ qua mọi chứng cứ. :: Giữ bình tĩnh, lắng nghe và phản biện lịch sự là thói quen ứng xử nhân văn.''')
# Existing topic A remains the original fixed exam; enrich metadata without altering content.
old=json.loads(pathlib.Path('/workspace/ict12-chu-de-a/exam-draft.json').read_text())
oldids=[]
for q in old['mcq']:
    z=q.copy();z['id']='a-old-'+str(q['id']);z['type']='mcq';z['topic']='A'
    z['lesson']=1 if int(q['id'])<=10 else 2
    z['section']='1. Khái niệm về AI' if z['lesson']==1 else '2. AI và một vài cảnh báo'
    z['review']=f'Bài {z["lesson"]} – {z["section"]} (trang {L[z["lesson"]]["pages"]})';oldids.append(z['id']);bank.append(z)
root.joinpath('lib/mcq.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2))
root.joinpath('lib/lessons.json').write_text(json.dumps(list(L.values()),ensure_ascii=False,indent=2))
root.joinpath('lib/old-a.json').write_text(json.dumps(old,ensure_ascii=False,indent=2))
print('MCQ',len(bank),collections.Counter(q['lesson'] for q in bank))
